window.MG_LAZY_DATA["data/lazy/courses/v11-google-willow-b094fafe08e73a91.json"]={sha256:"b094fafe08e73a919ac159ea1038d3b104c0118a5b4a2feabe8a99bc4d51ae67",value:{"id":"v11-google-willow","title":"Google Willow 表面碼系統","titleEn":"Google Willow surface-code system","category":"computing","subcategory":"quantum-qec","subcategoryTitle":"量子證據與錯誤更正","subcategoryTitleEn":"Quantum evidence and error correction","learningTrack":"quantum","learningSubdiscipline":"quantum-qec","learningTags":["quantum","quantum-qec","google-willow","quantum-superconducting"],"kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"curriculumVersion":11,"stepCount":12,"estimatedMinutes":420,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"sourceIds":["v11x-willow","v11x-willowpaper"],"stages":[{"id":"v11-google-willow-v11-stage1","order":1,"title":"系統邊界與基本原理","titleEn":"System boundaries and principles","description":"在Google Willow 表面碼系統案例中比較Willow 非諧能階與表面碼鄰接圖，各完成分析及驗證。","descriptionEn":"Analyze and validate willow anharmonic levels and surface-code adjacency within the Google Willow surface-code system case.","steps":[{"id":"v11-google-willow-v11-01","order":1,"sequence":1,"title":"超導電路與非諧性：架構分析","titleEn":"Superconducting circuits and anharmonicity: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":[],"objective":"針對Willow 非諧能階提出可反駁的超導電路與非諧性模型與驗證紀錄。","objectiveEn":"Produce a falsifiable superconducting circuits and anharmonicity model and evidence record for willow anharmonic levels.","instruction":"在「Google Willow 表面碼系統」的師傅示意與公開來源中，先辨識Willow 非諧能階。約瑟夫森接面提供非線性電感；非諧性使兩個能階可從其他能階分開控制。 建立超導電路與非諧性的輸入、狀態、輸出及邊界圖；本課重點是碼距、每循環邏輯錯誤與完整系統指標。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較理想諧振器與非諧振子的能階及洩漏。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify willow anharmonic levels in the mentor diagram and primary sources for Google Willow surface-code system. Josephson junctions supply nonlinear inductance; anharmonicity separates a controlled two-level subspace from other levels. Draw the inputs, states, outputs and boundaries of superconducting circuits and anharmonicity, focusing on code distance, logical error per cycle and system metrics. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare oscillator/anharmonic level spacings and leakage. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較理想諧振器與非諧振子的能階及洩漏。","observationEn":"Compare oscillator/anharmonic level spacings and leakage.","failure":"常見誤判：所有諧振器都天然等同隔離良好的二能階位元。","failureEn":"Common misconception: Every oscillator naturally forms an isolated two-level qubit.","check":"提交Willow 非諧能階的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for willow anharmonic levels.","knowledge":[{"id":"v11-google-willow-v11-01-k1","title":"超導電路與非諧性","titleEn":"Superconducting circuits and anharmonicity","text":"約瑟夫森接面提供非線性電感；非諧性使兩個能階可從其他能階分開控制。 本課架構對應：Willow 非諧能階","textEn":"Josephson junctions supply nonlinear inductance; anharmonicity separates a controlled two-level subspace from other levels. Course architecture correspondence: Willow anharmonic levels","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-01-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較理想諧振器與非諧振子的能階及洩漏。 應逐項保留基準與不確定度；所有諧振器都天然等同隔離良好的二能階位元。 是本單元要排除的誤解。","textEn":"Compare oscillator/anharmonic level spacings and leakage. Retain each reference and uncertainty; reject the misconception: Every oscillator naturally forms an isolated two-level qubit.","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-01-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 33 個獨立且相同錯誤率 p=0.0011 的事件，無錯誤機率 (1−p)^33=0.964332。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 33 independent events with equal p=0.0011: no-error probability (1−p)^33=0.964332. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-willow","v11x-willowpaper"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就Willow 非諧能階的「超導電路與非諧性」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for superconducting circuits and anharmonicity in willow anharmonic levels?","options":["約瑟夫森接面提供非線性電感；非諧性使兩個能階可從其他能階分開控制。","所有諧振器都天然等同隔離良好的二能階位元。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Josephson junctions supply nonlinear inductance; anharmonicity separates a controlled two-level subspace from other levels.","Every oscillator naturally forms an isolated two-level qubit.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"約瑟夫森接面提供非線性電感；非諧性使兩個能階可從其他能階分開控制。 比較理想諧振器與非諧振子的能階及洩漏。","explanationEn":"Josephson junctions supply nonlinear inductance; anharmonicity separates a controlled two-level subspace from other levels. Compare oscillator/anharmonic level spacings and leakage."}},{"id":"v11-google-willow-v11-02","order":2,"sequence":2,"title":"超導電路與非諧性：證據驗證","titleEn":"Superconducting circuits and anharmonicity: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-01"],"objective":"針對Willow 非諧能階提出可反駁的超導電路與非諧性模型與驗證紀錄。","objectiveEn":"Produce a falsifiable superconducting circuits and anharmonicity model and evidence record for willow anharmonic levels.","instruction":"沿用前一步「超導電路與非諧性」模型，檢查Willow 非諧能階的兩個假想案例。比較理想諧振器與非諧振子的能階及洩漏。 先訂可接受誤差，再比較預測與獨立計算；區分約瑟夫森接面提供非線性電感；非諧性使兩個能階可從其他能階分開控制。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous superconducting circuits and anharmonicity model to inspect two hypothetical cases involving willow anharmonic levels. Compare oscillator/anharmonic level spacings and leakage. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Josephson junctions supply nonlinear inductance; anharmonicity separates a controlled two-level subspace from other levels.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較理想諧振器與非諧振子的能階及洩漏。","observationEn":"Compare oscillator/anharmonic level spacings and leakage.","failure":"常見誤判：所有諧振器都天然等同隔離良好的二能階位元。","failureEn":"Common misconception: Every oscillator naturally forms an isolated two-level qubit.","check":"提交Willow 非諧能階的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for willow anharmonic levels.","knowledge":[{"id":"v11-google-willow-v11-02-k1","title":"超導電路與非諧性","titleEn":"Superconducting circuits and anharmonicity","text":"約瑟夫森接面提供非線性電感；非諧性使兩個能階可從其他能階分開控制。 本課架構對應：Willow 非諧能階","textEn":"Josephson junctions supply nonlinear inductance; anharmonicity separates a controlled two-level subspace from other levels. Course architecture correspondence: Willow anharmonic levels","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-02-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較理想諧振器與非諧振子的能階及洩漏。 應逐項保留基準與不確定度；所有諧振器都天然等同隔離良好的二能階位元。 是本單元要排除的誤解。","textEn":"Compare oscillator/anharmonic level spacings and leakage. Retain each reference and uncertainty; reject the misconception: Every oscillator naturally forms an isolated two-level qubit.","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-02-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 33 個獨立且相同錯誤率 p=0.0011 的事件，無錯誤機率 (1−p)^33=0.964332。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 33 independent events with equal p=0.0011: no-error probability (1−p)^33=0.964332. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-willow","v11x-willowpaper"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就Willow 非諧能階的「超導電路與非諧性」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for superconducting circuits and anharmonicity in willow anharmonic levels?","options":["所有諧振器都天然等同隔離良好的二能階位元。","比較理想諧振器與非諧振子的能階及洩漏。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Every oscillator naturally forms an isolated two-level qubit.","Compare oscillator/anharmonic level spacings and leakage.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"約瑟夫森接面提供非線性電感；非諧性使兩個能階可從其他能階分開控制。 比較理想諧振器與非諧振子的能階及洩漏。","explanationEn":"Josephson junctions supply nonlinear inductance; anharmonicity separates a controlled two-level subspace from other levels. Compare oscillator/anharmonic level spacings and leakage."}},{"id":"v11-google-willow-v11-03","order":3,"sequence":3,"title":"耦合圖與路由：架構分析","titleEn":"Coupling graphs and routing: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-02"],"objective":"針對表面碼鄰接圖提出可反駁的耦合圖與路由模型與驗證紀錄。","objectiveEn":"Produce a falsifiable coupling graphs and routing model and evidence record for surface-code adjacency.","instruction":"在「Google Willow 表面碼系統」的師傅示意與公開來源中，先辨識表面碼鄰接圖。原生可用的雙位元連線限制編譯；SWAP 路由增加深度與噪聲暴露。 建立耦合圖與路由的輸入、狀態、輸出及邊界圖；本課重點是碼距、每循環邏輯錯誤與完整系統指標。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。對相同邏輯電路比較兩張耦合圖的路由深度。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify surface-code adjacency in the mentor diagram and primary sources for Google Willow surface-code system. Native two-qubit connectivity constrains compilation; SWAP routing increases depth and noise exposure. Draw the inputs, states, outputs and boundaries of coupling graphs and routing, focusing on code distance, logical error per cycle and system metrics. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Route the same circuit on two graphs and compare depth. Record units, undisclosed parameters and model breakdown conditions.","observation":"對相同邏輯電路比較兩張耦合圖的路由深度。","observationEn":"Route the same circuit on two graphs and compare depth.","failure":"常見誤判：物理位元數相同就代表相同電路成本。","failureEn":"Common misconception: Equal physical-qubit counts imply equal circuit costs.","check":"提交表面碼鄰接圖的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for surface-code adjacency.","knowledge":[{"id":"v11-google-willow-v11-03-k1","title":"耦合圖與路由","titleEn":"Coupling graphs and routing","text":"原生可用的雙位元連線限制編譯；SWAP 路由增加深度與噪聲暴露。 本課架構對應：表面碼鄰接圖","textEn":"Native two-qubit connectivity constrains compilation; SWAP routing increases depth and noise exposure. Course architecture correspondence: Surface-code adjacency","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-03-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"對相同邏輯電路比較兩張耦合圖的路由深度。 應逐項保留基準與不確定度；物理位元數相同就代表相同電路成本。 是本單元要排除的誤解。","textEn":"Route the same circuit on two graphs and compare depth. Retain each reference and uncertainty; reject the misconception: Equal physical-qubit counts imply equal circuit costs.","sourceIds":["v11x-willow","v11x-willowpaper"]}],"quiz":{"question":"就表面碼鄰接圖的「耦合圖與路由」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for coupling graphs and routing in surface-code adjacency?","options":["物理位元數相同就代表相同電路成本。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","原生可用的雙位元連線限制編譯；SWAP 路由增加深度與噪聲暴露。"],"optionsEn":["Equal physical-qubit counts imply equal circuit costs.","Equal case averages rule out spatial, temporal and model errors.","Native two-qubit connectivity constrains compilation; SWAP routing increases depth and noise exposure."],"answer":2,"explanation":"原生可用的雙位元連線限制編譯；SWAP 路由增加深度與噪聲暴露。 對相同邏輯電路比較兩張耦合圖的路由深度。","explanationEn":"Native two-qubit connectivity constrains compilation; SWAP routing increases depth and noise exposure. Route the same circuit on two graphs and compare depth."}},{"id":"v11-google-willow-v11-04","order":4,"sequence":4,"title":"耦合圖與路由：證據驗證","titleEn":"Coupling graphs and routing: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-03"],"objective":"針對表面碼鄰接圖提出可反駁的耦合圖與路由模型與驗證紀錄。","objectiveEn":"Produce a falsifiable coupling graphs and routing model and evidence record for surface-code adjacency.","instruction":"沿用前一步「耦合圖與路由」模型，檢查表面碼鄰接圖的兩個假想案例。對相同邏輯電路比較兩張耦合圖的路由深度。 先訂可接受誤差，再比較預測與獨立計算；區分原生可用的雙位元連線限制編譯；SWAP 路由增加深度與噪聲暴露。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous coupling graphs and routing model to inspect two hypothetical cases involving surface-code adjacency. Route the same circuit on two graphs and compare depth. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Native two-qubit connectivity constrains compilation; SWAP routing increases depth and noise exposure.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"對相同邏輯電路比較兩張耦合圖的路由深度。","observationEn":"Route the same circuit on two graphs and compare depth.","failure":"常見誤判：物理位元數相同就代表相同電路成本。","failureEn":"Common misconception: Equal physical-qubit counts imply equal circuit costs.","check":"提交表面碼鄰接圖的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for surface-code adjacency.","knowledge":[{"id":"v11-google-willow-v11-04-k1","title":"耦合圖與路由","titleEn":"Coupling graphs and routing","text":"原生可用的雙位元連線限制編譯；SWAP 路由增加深度與噪聲暴露。 本課架構對應：表面碼鄰接圖","textEn":"Native two-qubit connectivity constrains compilation; SWAP routing increases depth and noise exposure. Course architecture correspondence: Surface-code adjacency","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-04-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"對相同邏輯電路比較兩張耦合圖的路由深度。 應逐項保留基準與不確定度；物理位元數相同就代表相同電路成本。 是本單元要排除的誤解。","textEn":"Route the same circuit on two graphs and compare depth. Retain each reference and uncertainty; reject the misconception: Equal physical-qubit counts imply equal circuit costs.","sourceIds":["v11x-willow","v11x-willowpaper"]}],"quiz":{"question":"就表面碼鄰接圖的「耦合圖與路由」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for coupling graphs and routing in surface-code adjacency?","options":["對相同邏輯電路比較兩張耦合圖的路由深度。","物理位元數相同就代表相同電路成本。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Route the same circuit on two graphs and compare depth.","Equal physical-qubit counts imply equal circuit costs.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"原生可用的雙位元連線限制編譯；SWAP 路由增加深度與噪聲暴露。 對相同邏輯電路比較兩張耦合圖的路由深度。","explanationEn":"Native two-qubit connectivity constrains compilation; SWAP routing increases depth and noise exposure. Route the same circuit on two graphs and compare depth."}}]},{"id":"v11-google-willow-v11-stage2","order":2,"title":"功能架構與量化模型","titleEn":"Functional architecture and quantitative models","description":"在Google Willow 表面碼系統案例中比較同時閘串擾與反覆量測與重置，各完成分析及驗證。","descriptionEn":"Analyze and validate concurrent-gate crosstalk and repeated measurement and reset within the Google Willow surface-code system case.","steps":[{"id":"v11-google-willow-v11-05","order":1,"sequence":5,"title":"微波控制與串擾：架構分析","titleEn":"Microwave control and crosstalk: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-04"],"objective":"針對同時閘串擾提出可反駁的微波控制與串擾模型與驗證紀錄。","objectiveEn":"Produce a falsifiable microwave control and crosstalk model and evidence record for concurrent-gate crosstalk.","instruction":"在「Google Willow 表面碼系統」的師傅示意與公開來源中，先辨識同時閘串擾。控制脈衝的頻譜可同時激發鄰近模態；閘錯誤不只是振幅偏差。 建立微波控制與串擾的輸入、狀態、輸出及邊界圖；本課重點是碼距、每循環邏輯錯誤與完整系統指標。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較單獨與同時操作的假想錯誤矩陣。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify concurrent-gate crosstalk in the mentor diagram and primary sources for Google Willow surface-code system. Control spectra can excite neighboring modes; gate error is not only amplitude error. Draw the inputs, states, outputs and boundaries of microwave control and crosstalk, focusing on code distance, logical error per cycle and system metrics. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare hypothetical isolated and simultaneous-operation error matrices. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較單獨與同時操作的假想錯誤矩陣。","observationEn":"Compare hypothetical isolated and simultaneous-operation error matrices.","failure":"常見誤判：單獨量到的閘精度可直接代表同時操作精度。","failureEn":"Common misconception: Isolated gate fidelity directly equals simultaneous-operation fidelity.","check":"提交同時閘串擾的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for concurrent-gate crosstalk.","knowledge":[{"id":"v11-google-willow-v11-05-k1","title":"微波控制與串擾","titleEn":"Microwave control and crosstalk","text":"控制脈衝的頻譜可同時激發鄰近模態；閘錯誤不只是振幅偏差。 本課架構對應：同時閘串擾","textEn":"Control spectra can excite neighboring modes; gate error is not only amplitude error. Course architecture correspondence: Concurrent-gate crosstalk","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-05-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較單獨與同時操作的假想錯誤矩陣。 應逐項保留基準與不確定度；單獨量到的閘精度可直接代表同時操作精度。 是本單元要排除的誤解。","textEn":"Compare hypothetical isolated and simultaneous-operation error matrices. Retain each reference and uncertainty; reject the misconception: Isolated gate fidelity directly equals simultaneous-operation fidelity.","sourceIds":["v11x-willow","v11x-willowpaper"]}],"quiz":{"question":"就同時閘串擾的「微波控制與串擾」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for microwave control and crosstalk in concurrent-gate crosstalk?","options":["單獨量到的閘精度可直接代表同時操作精度。","控制脈衝的頻譜可同時激發鄰近模態；閘錯誤不只是振幅偏差。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Isolated gate fidelity directly equals simultaneous-operation fidelity.","Control spectra can excite neighboring modes; gate error is not only amplitude error.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"控制脈衝的頻譜可同時激發鄰近模態；閘錯誤不只是振幅偏差。 比較單獨與同時操作的假想錯誤矩陣。","explanationEn":"Control spectra can excite neighboring modes; gate error is not only amplitude error. Compare hypothetical isolated and simultaneous-operation error matrices."}},{"id":"v11-google-willow-v11-06","order":2,"sequence":6,"title":"微波控制與串擾：證據驗證","titleEn":"Microwave control and crosstalk: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-05"],"objective":"針對同時閘串擾提出可反駁的微波控制與串擾模型與驗證紀錄。","objectiveEn":"Produce a falsifiable microwave control and crosstalk model and evidence record for concurrent-gate crosstalk.","instruction":"沿用前一步「微波控制與串擾」模型，檢查同時閘串擾的兩個假想案例。比較單獨與同時操作的假想錯誤矩陣。 先訂可接受誤差，再比較預測與獨立計算；區分控制脈衝的頻譜可同時激發鄰近模態；閘錯誤不只是振幅偏差。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous microwave control and crosstalk model to inspect two hypothetical cases involving concurrent-gate crosstalk. Compare hypothetical isolated and simultaneous-operation error matrices. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Control spectra can excite neighboring modes; gate error is not only amplitude error.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較單獨與同時操作的假想錯誤矩陣。","observationEn":"Compare hypothetical isolated and simultaneous-operation error matrices.","failure":"常見誤判：單獨量到的閘精度可直接代表同時操作精度。","failureEn":"Common misconception: Isolated gate fidelity directly equals simultaneous-operation fidelity.","check":"提交同時閘串擾的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for concurrent-gate crosstalk.","knowledge":[{"id":"v11-google-willow-v11-06-k1","title":"微波控制與串擾","titleEn":"Microwave control and crosstalk","text":"控制脈衝的頻譜可同時激發鄰近模態；閘錯誤不只是振幅偏差。 本課架構對應：同時閘串擾","textEn":"Control spectra can excite neighboring modes; gate error is not only amplitude error. Course architecture correspondence: Concurrent-gate crosstalk","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-06-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較單獨與同時操作的假想錯誤矩陣。 應逐項保留基準與不確定度；單獨量到的閘精度可直接代表同時操作精度。 是本單元要排除的誤解。","textEn":"Compare hypothetical isolated and simultaneous-operation error matrices. Retain each reference and uncertainty; reject the misconception: Isolated gate fidelity directly equals simultaneous-operation fidelity.","sourceIds":["v11x-willow","v11x-willowpaper"]}],"quiz":{"question":"就同時閘串擾的「微波控制與串擾」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for microwave control and crosstalk in concurrent-gate crosstalk?","options":["單獨量到的閘精度可直接代表同時操作精度。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","比較單獨與同時操作的假想錯誤矩陣。"],"optionsEn":["Isolated gate fidelity directly equals simultaneous-operation fidelity.","Equal case averages rule out spatial, temporal and model errors.","Compare hypothetical isolated and simultaneous-operation error matrices."],"answer":2,"explanation":"控制脈衝的頻譜可同時激發鄰近模態；閘錯誤不只是振幅偏差。 比較單獨與同時操作的假想錯誤矩陣。","explanationEn":"Control spectra can excite neighboring modes; gate error is not only amplitude error. Compare hypothetical isolated and simultaneous-operation error matrices."}},{"id":"v11-google-willow-v11-07","order":3,"sequence":7,"title":"色散讀出與指派誤差：架構分析","titleEn":"Dispersive readout and assignment error: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-06"],"objective":"針對反覆量測與重置提出可反駁的色散讀出與指派誤差模型與驗證紀錄。","objectiveEn":"Produce a falsifiable dispersive readout and assignment error model and evidence record for repeated measurement and reset.","instruction":"在「Google Willow 表面碼系統」的師傅示意與公開來源中，先辨識反覆量測與重置。讀出將位元狀態映射到共振器響應；混淆矩陣與相干誤差是不同證據。 建立色散讀出與指派誤差的輸入、狀態、輸出及邊界圖；本課重點是碼距、每循環邏輯錯誤與完整系統指標。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。由標籤資料重算讀出混淆矩陣並保留樣本數。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify repeated measurement and reset in the mentor diagram and primary sources for Google Willow surface-code system. Readout maps states to resonator response; a confusion matrix differs from coherent-error evidence. Draw the inputs, states, outputs and boundaries of dispersive readout and assignment error, focusing on code distance, logical error per cycle and system metrics. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Recalculate a labeled readout confusion matrix with sample counts. Record units, undisclosed parameters and model breakdown conditions.","observation":"由標籤資料重算讀出混淆矩陣並保留樣本數。","observationEn":"Recalculate a labeled readout confusion matrix with sample counts.","failure":"常見誤判：讀出錯誤與閘錯誤是可互換的單一指標。","failureEn":"Common misconception: Readout and gate errors are interchangeable metrics.","check":"提交反覆量測與重置的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for repeated measurement and reset.","knowledge":[{"id":"v11-google-willow-v11-07-k1","title":"色散讀出與指派誤差","titleEn":"Dispersive readout and assignment error","text":"讀出將位元狀態映射到共振器響應；混淆矩陣與相干誤差是不同證據。 本課架構對應：反覆量測與重置","textEn":"Readout maps states to resonator response; a confusion matrix differs from coherent-error evidence. Course architecture correspondence: Repeated measurement and reset","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-07-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"由標籤資料重算讀出混淆矩陣並保留樣本數。 應逐項保留基準與不確定度；讀出錯誤與閘錯誤是可互換的單一指標。 是本單元要排除的誤解。","textEn":"Recalculate a labeled readout confusion matrix with sample counts. Retain each reference and uncertainty; reject the misconception: Readout and gate errors are interchangeable metrics.","sourceIds":["v11x-willow","v11x-willowpaper"]}],"quiz":{"question":"就反覆量測與重置的「色散讀出與指派誤差」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for dispersive readout and assignment error in repeated measurement and reset?","options":["讀出將位元狀態映射到共振器響應；混淆矩陣與相干誤差是不同證據。","讀出錯誤與閘錯誤是可互換的單一指標。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Readout maps states to resonator response; a confusion matrix differs from coherent-error evidence.","Readout and gate errors are interchangeable metrics.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"讀出將位元狀態映射到共振器響應；混淆矩陣與相干誤差是不同證據。 由標籤資料重算讀出混淆矩陣並保留樣本數。","explanationEn":"Readout maps states to resonator response; a confusion matrix differs from coherent-error evidence. Recalculate a labeled readout confusion matrix with sample counts."}},{"id":"v11-google-willow-v11-08","order":4,"sequence":8,"title":"色散讀出與指派誤差：證據驗證","titleEn":"Dispersive readout and assignment error: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-07"],"objective":"針對反覆量測與重置提出可反駁的色散讀出與指派誤差模型與驗證紀錄。","objectiveEn":"Produce a falsifiable dispersive readout and assignment error model and evidence record for repeated measurement and reset.","instruction":"沿用前一步「色散讀出與指派誤差」模型，檢查反覆量測與重置的兩個假想案例。由標籤資料重算讀出混淆矩陣並保留樣本數。 先訂可接受誤差，再比較預測與獨立計算；區分讀出將位元狀態映射到共振器響應；混淆矩陣與相干誤差是不同證據。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous dispersive readout and assignment error model to inspect two hypothetical cases involving repeated measurement and reset. Recalculate a labeled readout confusion matrix with sample counts. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Readout maps states to resonator response; a confusion matrix differs from coherent-error evidence.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"由標籤資料重算讀出混淆矩陣並保留樣本數。","observationEn":"Recalculate a labeled readout confusion matrix with sample counts.","failure":"常見誤判：讀出錯誤與閘錯誤是可互換的單一指標。","failureEn":"Common misconception: Readout and gate errors are interchangeable metrics.","check":"提交反覆量測與重置的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for repeated measurement and reset.","knowledge":[{"id":"v11-google-willow-v11-08-k1","title":"色散讀出與指派誤差","titleEn":"Dispersive readout and assignment error","text":"讀出將位元狀態映射到共振器響應；混淆矩陣與相干誤差是不同證據。 本課架構對應：反覆量測與重置","textEn":"Readout maps states to resonator response; a confusion matrix differs from coherent-error evidence. Course architecture correspondence: Repeated measurement and reset","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-08-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"由標籤資料重算讀出混淆矩陣並保留樣本數。 應逐項保留基準與不確定度；讀出錯誤與閘錯誤是可互換的單一指標。 是本單元要排除的誤解。","textEn":"Recalculate a labeled readout confusion matrix with sample counts. Retain each reference and uncertainty; reject the misconception: Readout and gate errors are interchangeable metrics.","sourceIds":["v11x-willow","v11x-willowpaper"]}],"quiz":{"question":"就反覆量測與重置的「色散讀出與指派誤差」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for dispersive readout and assignment error in repeated measurement and reset?","options":["讀出錯誤與閘錯誤是可互換的單一指標。","由標籤資料重算讀出混淆矩陣並保留樣本數。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Readout and gate errors are interchangeable metrics.","Recalculate a labeled readout confusion matrix with sample counts.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"讀出將位元狀態映射到共振器響應；混淆矩陣與相干誤差是不同證據。 由標籤資料重算讀出混淆矩陣並保留樣本數。","explanationEn":"Readout maps states to resonator response; a confusion matrix differs from coherent-error evidence. Recalculate a labeled readout confusion matrix with sample counts."}}]},{"id":"v11-google-willow-v11-stage3","order":3,"title":"獨立驗證與工程交接","titleEn":"Independent validation and engineering handoff","description":"在Google Willow 表面碼系統案例中比較冷卻與訊號預算與跨碼距閾值比較，各完成分析及驗證。","descriptionEn":"Analyze and validate cooling and signal budgets and cross-distance threshold comparison within the Google Willow surface-code system case.","steps":[{"id":"v11-google-willow-v11-09","order":1,"sequence":9,"title":"低溫熱路與訊號負載：架構分析","titleEn":"Cryogenic heat paths and signal loads: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-08"],"objective":"針對冷卻與訊號預算提出可反駁的低溫熱路與訊號負載模型與驗證紀錄。","objectiveEn":"Produce a falsifiable cryogenic heat paths and signal loads model and evidence record for cooling and signal budgets.","instruction":"在「Google Willow 表面碼系統」的師傅示意與公開來源中，先辨識冷卻與訊號預算。每條控制線帶入熱與雜訊；低溫層的冷卻能力需按溫度分開預算。 建立低溫熱路與訊號負載的輸入、狀態、輸出及邊界圖；本課重點是碼距、每循環邏輯錯誤與完整系統指標。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。建立各溫層的負載、裕度與線數假想表。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify cooling and signal budgets in the mentor diagram and primary sources for Google Willow surface-code system. Each control line carries heat and noise; cooling capacity is budgeted separately by temperature stage. Draw the inputs, states, outputs and boundaries of cryogenic heat paths and signal loads, focusing on code distance, logical error per cycle and system metrics. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Build an assumed load, margin and line-count table per stage. Record units, undisclosed parameters and model breakdown conditions.","observation":"建立各溫層的負載、裕度與線數假想表。","observationEn":"Build an assumed load, margin and line-count table per stage.","failure":"常見誤判：室溫機櫃功耗等於稀釋冷凍機最低溫熱負載。","failureEn":"Common misconception: Room-temperature rack power equals the coldest-stage thermal load.","check":"提交冷卻與訊號預算的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for cooling and signal budgets.","knowledge":[{"id":"v11-google-willow-v11-09-k1","title":"低溫熱路與訊號負載","titleEn":"Cryogenic heat paths and signal loads","text":"每條控制線帶入熱與雜訊；低溫層的冷卻能力需按溫度分開預算。 本課架構對應：冷卻與訊號預算","textEn":"Each control line carries heat and noise; cooling capacity is budgeted separately by temperature stage. Course architecture correspondence: Cooling and signal budgets","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-09-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"建立各溫層的負載、裕度與線數假想表。 應逐項保留基準與不確定度；室溫機櫃功耗等於稀釋冷凍機最低溫熱負載。 是本單元要排除的誤解。","textEn":"Build an assumed load, margin and line-count table per stage. Retain each reference and uncertainty; reject the misconception: Room-temperature rack power equals the coldest-stage thermal load.","sourceIds":["v11x-willow","v11x-willowpaper"]}],"quiz":{"question":"就冷卻與訊號預算的「低溫熱路與訊號負載」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for cryogenic heat paths and signal loads in cooling and signal budgets?","options":["室溫機櫃功耗等於稀釋冷凍機最低溫熱負載。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","每條控制線帶入熱與雜訊；低溫層的冷卻能力需按溫度分開預算。"],"optionsEn":["Room-temperature rack power equals the coldest-stage thermal load.","Equal case averages rule out spatial, temporal and model errors.","Each control line carries heat and noise; cooling capacity is budgeted separately by temperature stage."],"answer":2,"explanation":"每條控制線帶入熱與雜訊；低溫層的冷卻能力需按溫度分開預算。 建立各溫層的負載、裕度與線數假想表。","explanationEn":"Each control line carries heat and noise; cooling capacity is budgeted separately by temperature stage. Build an assumed load, margin and line-count table per stage."}},{"id":"v11-google-willow-v11-10","order":2,"sequence":10,"title":"低溫熱路與訊號負載：證據驗證","titleEn":"Cryogenic heat paths and signal loads: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-09"],"objective":"針對冷卻與訊號預算提出可反駁的低溫熱路與訊號負載模型與驗證紀錄。","objectiveEn":"Produce a falsifiable cryogenic heat paths and signal loads model and evidence record for cooling and signal budgets.","instruction":"沿用前一步「低溫熱路與訊號負載」模型，檢查冷卻與訊號預算的兩個假想案例。建立各溫層的負載、裕度與線數假想表。 先訂可接受誤差，再比較預測與獨立計算；區分每條控制線帶入熱與雜訊；低溫層的冷卻能力需按溫度分開預算。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous cryogenic heat paths and signal loads model to inspect two hypothetical cases involving cooling and signal budgets. Build an assumed load, margin and line-count table per stage. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Each control line carries heat and noise; cooling capacity is budgeted separately by temperature stage.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"建立各溫層的負載、裕度與線數假想表。","observationEn":"Build an assumed load, margin and line-count table per stage.","failure":"常見誤判：室溫機櫃功耗等於稀釋冷凍機最低溫熱負載。","failureEn":"Common misconception: Room-temperature rack power equals the coldest-stage thermal load.","check":"提交冷卻與訊號預算的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for cooling and signal budgets.","knowledge":[{"id":"v11-google-willow-v11-10-k1","title":"低溫熱路與訊號負載","titleEn":"Cryogenic heat paths and signal loads","text":"每條控制線帶入熱與雜訊；低溫層的冷卻能力需按溫度分開預算。 本課架構對應：冷卻與訊號預算","textEn":"Each control line carries heat and noise; cooling capacity is budgeted separately by temperature stage. Course architecture correspondence: Cooling and signal budgets","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-10-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"建立各溫層的負載、裕度與線數假想表。 應逐項保留基準與不確定度；室溫機櫃功耗等於稀釋冷凍機最低溫熱負載。 是本單元要排除的誤解。","textEn":"Build an assumed load, margin and line-count table per stage. Retain each reference and uncertainty; reject the misconception: Room-temperature rack power equals the coldest-stage thermal load.","sourceIds":["v11x-willow","v11x-willowpaper"]}],"quiz":{"question":"就冷卻與訊號預算的「低溫熱路與訊號負載」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for cryogenic heat paths and signal loads in cooling and signal budgets?","options":["建立各溫層的負載、裕度與線數假想表。","室溫機櫃功耗等於稀釋冷凍機最低溫熱負載。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Build an assumed load, margin and line-count table per stage.","Room-temperature rack power equals the coldest-stage thermal load.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"每條控制線帶入熱與雜訊；低溫層的冷卻能力需按溫度分開預算。 建立各溫層的負載、裕度與線數假想表。","explanationEn":"Each control line carries heat and noise; cooling capacity is budgeted separately by temperature stage. Build an assumed load, margin and line-count table per stage."}},{"id":"v11-google-willow-v11-11","order":3,"sequence":11,"title":"錯誤更正與邏輯證據：架構分析","titleEn":"Error correction and logical evidence: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-10"],"objective":"針對跨碼距閾值比較提出可反駁的錯誤更正與邏輯證據模型與驗證紀錄。","objectiveEn":"Produce a falsifiable error correction and logical evidence model and evidence record for cross-distance threshold comparison.","instruction":"在「Google Willow 表面碼系統」的師傅示意與公開來源中，先辨識跨碼距閾值比較。邏輯錯誤率與物理錯誤率不同；閾值行為需跨碼距且控制實驗條件。 建立錯誤更正與邏輯證據的輸入、狀態、輸出及邊界圖；本課重點是碼距、每循環邏輯錯誤與完整系統指標。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較碼距增加時的每循環邏輯錯誤與置信區間。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify cross-distance threshold comparison in the mentor diagram and primary sources for Google Willow surface-code system. Logical and physical error rates differ; threshold behavior requires comparisons across code distances under controlled conditions. Draw the inputs, states, outputs and boundaries of error correction and logical evidence, focusing on code distance, logical error per cycle and system metrics. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare logical error per cycle and confidence intervals across code distances. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較碼距增加時的每循環邏輯錯誤與置信區間。","observationEn":"Compare logical error per cycle and confidence intervals across code distances.","failure":"常見誤判：增加物理位元必然降低邏輯錯誤。","failureEn":"Common misconception: More physical qubits necessarily reduce logical error.","check":"提交跨碼距閾值比較的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for cross-distance threshold comparison.","knowledge":[{"id":"v11-google-willow-v11-11-k1","title":"錯誤更正與邏輯證據","titleEn":"Error correction and logical evidence","text":"邏輯錯誤率與物理錯誤率不同；閾值行為需跨碼距且控制實驗條件。 本課架構對應：跨碼距閾值比較","textEn":"Logical and physical error rates differ; threshold behavior requires comparisons across code distances under controlled conditions. Course architecture correspondence: Cross-distance threshold comparison","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-11-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較碼距增加時的每循環邏輯錯誤與置信區間。 應逐項保留基準與不確定度；增加物理位元必然降低邏輯錯誤。 是本單元要排除的誤解。","textEn":"Compare logical error per cycle and confidence intervals across code distances. Retain each reference and uncertainty; reject the misconception: More physical qubits necessarily reduce logical error.","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-11-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 33 個獨立且相同錯誤率 p=0.0011 的事件，無錯誤機率 (1−p)^33=0.964332。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 33 independent events with equal p=0.0011: no-error probability (1−p)^33=0.964332. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-willow","v11x-willowpaper"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就跨碼距閾值比較的「錯誤更正與邏輯證據」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for error correction and logical evidence in cross-distance threshold comparison?","options":["增加物理位元必然降低邏輯錯誤。","邏輯錯誤率與物理錯誤率不同；閾值行為需跨碼距且控制實驗條件。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["More physical qubits necessarily reduce logical error.","Logical and physical error rates differ; threshold behavior requires comparisons across code distances under controlled conditions.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"邏輯錯誤率與物理錯誤率不同；閾值行為需跨碼距且控制實驗條件。 比較碼距增加時的每循環邏輯錯誤與置信區間。","explanationEn":"Logical and physical error rates differ; threshold behavior requires comparisons across code distances under controlled conditions. Compare logical error per cycle and confidence intervals across code distances."}},{"id":"v11-google-willow-v11-12","order":4,"sequence":12,"title":"錯誤更正與邏輯證據：證據驗證","titleEn":"Error correction and logical evidence: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-willow","v11x-willowpaper"],"prerequisiteIds":["v11-google-willow-v11-11"],"objective":"針對跨碼距閾值比較提出可反駁的錯誤更正與邏輯證據模型與驗證紀錄。","objectiveEn":"Produce a falsifiable error correction and logical evidence model and evidence record for cross-distance threshold comparison.","instruction":"沿用前一步「錯誤更正與邏輯證據」模型，檢查跨碼距閾值比較的兩個假想案例。比較碼距增加時的每循環邏輯錯誤與置信區間。 先訂可接受誤差，再比較預測與獨立計算；區分邏輯錯誤率與物理錯誤率不同；閾值行為需跨碼距且控制實驗條件。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous error correction and logical evidence model to inspect two hypothetical cases involving cross-distance threshold comparison. Compare logical error per cycle and confidence intervals across code distances. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Logical and physical error rates differ; threshold behavior requires comparisons across code distances under controlled conditions.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較碼距增加時的每循環邏輯錯誤與置信區間。","observationEn":"Compare logical error per cycle and confidence intervals across code distances.","failure":"常見誤判：增加物理位元必然降低邏輯錯誤。","failureEn":"Common misconception: More physical qubits necessarily reduce logical error.","check":"提交跨碼距閾值比較的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for cross-distance threshold comparison.","knowledge":[{"id":"v11-google-willow-v11-12-k1","title":"錯誤更正與邏輯證據","titleEn":"Error correction and logical evidence","text":"邏輯錯誤率與物理錯誤率不同；閾值行為需跨碼距且控制實驗條件。 本課架構對應：跨碼距閾值比較","textEn":"Logical and physical error rates differ; threshold behavior requires comparisons across code distances under controlled conditions. Course architecture correspondence: Cross-distance threshold comparison","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-12-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較碼距增加時的每循環邏輯錯誤與置信區間。 應逐項保留基準與不確定度；增加物理位元必然降低邏輯錯誤。 是本單元要排除的誤解。","textEn":"Compare logical error per cycle and confidence intervals across code distances. Retain each reference and uncertainty; reject the misconception: More physical qubits necessarily reduce logical error.","sourceIds":["v11x-willow","v11x-willowpaper"]},{"id":"v11-google-willow-v11-12-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 33 個獨立且相同錯誤率 p=0.0011 的事件，無錯誤機率 (1−p)^33=0.964332。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 33 independent events with equal p=0.0011: no-error probability (1−p)^33=0.964332. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-willow","v11x-willowpaper"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就跨碼距閾值比較的「錯誤更正與邏輯證據」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for error correction and logical evidence in cross-distance threshold comparison?","options":["增加物理位元必然降低邏輯錯誤。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","比較碼距增加時的每循環邏輯錯誤與置信區間。"],"optionsEn":["More physical qubits necessarily reduce logical error.","Equal case averages rule out spatial, temporal and model errors.","Compare logical error per cycle and confidence intervals across code distances."],"answer":2,"explanation":"邏輯錯誤率與物理錯誤率不同；閾值行為需跨碼距且控制實驗條件。 比較碼距增加時的每循環邏輯錯誤與置信區間。","explanationEn":"Logical and physical error rates differ; threshold behavior requires comparisons across code distances under controlled conditions. Compare logical error per cycle and confidence intervals across code distances."}}]}],"summary":"以碼距、每循環邏輯錯誤與完整系統指標解析Google Willow 表面碼系統：六個原理與架構單元、十二項可保存的分析及驗證作業，附假想量化例、來源及衍生工程比較。","summaryEn":"Explore Google Willow surface-code system through code distance, logical error per cycle and system metrics: six principle/architecture units and twelve saved analysis/validation tasks, with an assumed numerical example, primary sources and related engineering comparisons.","scope":"依公開研究與裝置資料編寫的離線模型、編譯及證據判讀。不是實機組裝、雷射或低溫作業SOP；假想算例不代表廠商精度、量子優勢或容錯能力。研發宣稱與已驗證觀測分開標示。 特定表面碼記憶實驗的閾值以下結果，不等同完整容錯通用電腦或任意工作負載上的量子優勢。","scopeEn":"Offline models, compilation and evidence interpretation from public research/device sources. Not hardware assembly, laser/cryogenic SOPs; assumed examples are not vendor fidelity, advantage or fault tolerance. Development claims and demonstrated observations remain distinct. Below-threshold results from particular surface-code memory experiments do not establish a complete fault-tolerant universal computer or advantage on arbitrary workloads.","workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"假設 33 個獨立且相同錯誤率 p=0.0011 的事件，無錯誤機率 (1−p)^33=0.964332。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 33 independent events with equal p=0.0011: no-error probability (1−p)^33=0.964332. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","assumptions":"數值是本課自行設定的假設，不代表實機量測、產品額定或操作參數；改變模型邊界後必須重算。","assumptionsEn":"Inputs are independently selected assumptions, not measured hardware, ratings or operating parameters; recalculate after boundary changes.","sourceScope":"原創數值練習；來源支援公開架構及領域原理，不宣稱來源提供這組假想數據。","sourceScopeEn":"Original numerical exercise; sources support public architecture and principles, not these assumed measurements."},"diagram":{"type":"network","labels":["Willow 非諧能階","表面碼鄰接圖","同時閘串擾","反覆量測與重置","冷卻與訊號預算","跨碼距閾值比較"],"labelsEn":["Willow anharmonic levels","Surface-code adjacency","Concurrent-gate crosstalk","Repeated measurement and reset","Cooling and signal budgets","Cross-distance threshold comparison"],"original":true,"notToScale":true},"vendorHints":[{"name":"Google Quantum AI","nameEn":"Google Quantum AI","url":"https://quantumai.google/quantumcomputer","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-willow"]},{"name":"Google Quantum AI / Nature","nameEn":"Google Quantum AI / Nature","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11864966/","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-willowpaper"]}],"architectureNodes":[["微波控制器","Microwave controller"],["超導QPU","Superconducting QPU"],["讀出共振器","Readout resonator"],["經典解碼器","Classical decoder"],["低溫熱路","Cryogenic heat path"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,0],[4,1]],"architectureFamily":"qpu","educationEdition":11,"enrichmentVersion":11}};
